#!/usr/bin/env python3
from pathlib import Path
import json
OUT=Path(__file__).resolve().parents[3]/'benchmarks/electronics_v3_quality_v1/cases.v1.jsonl'
rows=[]
def add(cid,cat,prompt,model,measurement,prediction,abstain=False):
    rows.append({'schema_version':1,'case_id':cid,'category':cat,'language':'pl','training_exclusion':True,'prompt':prompt,'reference':{'diagnostic_model':model,'discriminating_measurement':measurement,'predicted_result':prediction,'must_abstain':abstain}})
for i,(vin,rail,load) in enumerate([(12,5,0.8),(24,5,1.1),(12,3.3,0.6),(24,3.3,0.9),(12,5,1.4),(24,5,1.6)],1):
    add(f'P55-SUP-{i:02d}','schematic_symptom_measurements',f'Układ: wejście {vin} V -> bezpiecznik -> dławik -> stabilizator {rail} V. Na biegu jałowym szyna ma {rail:.1f} V. Przy obciążeniu {load} A napięcie spada o 35%, ale napięcie na wejściu płytki pozostaje prawidłowe. Zaproponuj najbardziej prawdopodobny model usterki, jeden pomiar rozdzielający i przewidywany wynik.', 'rezystancja szeregowa lub uszkodzenie w torze zasilania przed stabilizatorem albo dropout stabilizatora pod obciążeniem', 'jednoczesny pomiar napięcia przed i za elementami toru wejściowego oraz na wejściu i wyjściu stabilizatora podczas skoku obciążenia', 'jeśli winny jest tor wejściowy spadek pojawi się przed wejściem stabilizatora; jeśli wejście pozostanie stabilne a wyjście siądzie winny jest stabilizator lub jego otoczenie')
for i,(sig,ref,adc) in enumerate([(2.1,5.0,0.15),(3.8,5.0,4.85),(1.2,3.3,0.05),(2.7,3.3,3.20),(0.9,5.0,4.6),(4.1,5.0,0.4)],1):
    add(f'P55-ANA-{i:02d}','good_bad_channels',f'Dwa identyczne kanały analogowe. Kanał dobry: sygnał {sig} V dociera do ADC poprawnie. Kanał zły ma prawidłowe zasilania i referencję {ref} V, ale pin ADC pokazuje {adc} V mimo prawidłowego napięcia na wejściu kanału. Podaj model usterki, pomiar rozdzielający i przewidywany wynik.', 'lokalna usterka toru analogowego między wejściem kanału a pinem ADC: rezystor szeregowy, filtr, wzmacniacz/bufor lub zwarcie przy ADC', 'porównanie napięcia kanału dobrego i złego punkt po punkcie po obu stronach rezystora/filtra/bufora aż do pinu ADC', 'kanały będą zgodne do miejsca uszkodzenia, a za nim kanał zły odchyli się od dobrego')
for i,(freq,duty,gate) in enumerate([(1000,50,3.1),(500,30,2.4),(2000,70,4.0),(800,40,1.8),(1500,60,3.3),(250,25,2.0)],1):
    add(f'P55-WAV-{i:02d}','numeric_waveform',f'Sterowanie MOSFET-em: z MCU wychodzi PWM {freq} Hz, duty {duty}%, amplituda 3.3 V i jest stabilna. Na bramce po driverze amplituda po nagrzaniu spada do {gate} V, zbocza wydłużają się, a prąd obciążenia maleje. Co diagnozujesz i jak to rozdzielisz pomiarem?', 'usterka stopnia drivera bramki lub jego zasilania, ujawniająca się termicznie; źródło PWM MCU jest mniej prawdopodobne', 'równoczesny oscyloskop wejścia drivera, jego zasilania i wyjścia bramkowego podczas grzania/chłodzenia', 'wejście PWM pozostanie poprawne, a degradacja pojawi się na zasilaniu lub wyjściu drivera i będzie korelować z temperaturą')
for i,(temp,part) in enumerate([(68,'stabilizatora'),(74,'drivera'),(82,'wzmacniacza operacyjnego'),(63,'złącza'),(77,'rezystora mocy'),(71,'przelotki/połączenia lutowanego')],1):
    add(f'P55-THM-{i:02d}','thermal_intermittent',f'Płytka działa na zimno. Po osiągnięciu około {temp} °C pojawia się usterka. Lokalny nawiew chłodzący okolice {part} natychmiast przywraca działanie, ale chłodzenie reszty PCB nie. Podaj model usterki, test rozdzielający i oczekiwany rezultat.', f'termiczna usterka lokalna w rejonie {part}: element półprzewodnikowy, połączenie lub lut zmieniający parametry z temperaturą', f'kontrolowane lokalne grzanie i chłodzenie {part} przy ciągłym monitoringu sygnału wejściowego, wyjściowego i zasilania', 'usterka powinna powtarzalnie pojawiać się i znikać wraz z temperaturą badanego rejonu, podczas gdy sygnały wejściowe z wcześniejszego stopnia pozostaną stabilne')
for i,(rail,res,inj) in enumerate([(5,3.2,1.0),(3.3,1.8,0.8),(12,8.5,1.5),(5,0.9,0.6),(3.3,4.7,1.0),(12,2.4,1.2)],1):
    add(f'P55-SHT-{i:02d}','pcb_short',f'Po wyłączeniu zasilania szyna {rail} V ma tylko {res} Ω do masy. Zasilacz laboratoryjny przy normalnym uruchomieniu wchodzi w limit prądu. Można bezpiecznie wykonać ograniczoną iniekcję do {inj} A. Jaki model usterki, jaki pomiar i czego oczekujesz?', 'zwarcie lub silne upływowe obciążenie na szynie, np. kondensator MLCC albo uszkodzony układ scalony', 'iniekcja niskiego napięcia z ograniczeniem prądu i lokalizacja punktu grzania kamerą termiczną/IPA przy równoległym pomiarze spadków napięcia', 'element powodujący zwarcie powinien wykazać lokalny wzrost temperatury lub największy gradient spadku napięcia; bez hotspotu nie należy wskazywać części na chybił-trafił')
for i,(good,bad,node) in enumerate([(2.4,0.0,'wyjściu wzmacniacza'),(5.0,1.1,'za rezystorem szeregowym'),(3.3,2.0,'na wyjściu bufora'),(8.0,3.2,'na drenie tranzystora'),(1.65,0.2,'na wejściu ADC'),(12.0,6.4,'za stykiem złącza')],1):
    add(f'P55-CMP-{i:02d}','good_bad_channel_comparison',f'Są dwa identyczne kanały na tej samej płytce i wspólnym zasilaniu. Dobry kanał ma {good} V, zły {bad} V w punkcie "{node}". Wcześniejsze węzły obu kanałów mają praktycznie identyczne wartości. Jak wykorzystasz kanał dobry do diagnozy?', 'lokalna usterka w złym kanale w stopniu pomiędzy ostatnim zgodnym węzłem a pierwszym różniącym się węzłem', 'porównanie obu kanałów punkt-po-punkcie pod tym samym obciążeniem, w tym wejścia i wyjścia podejrzanego stopnia', 'pierwsza trwała różnica powinna pojawić się w uszkodzonym stopniu; wspólne zasilanie pozostanie zgodne na obu kanałach')
for i,p in enumerate([
    'Urządzenie czasem się resetuje. Nie ma schematu, logów ani pomiarów napięć.',
    'Wyjście nie steruje obciążeniem. Nie wiadomo, czy dociera komenda wejściowa ani czy jest zasilanie drivera.',
    'Po nagrzaniu układ przestaje działać, ale nie wykonano lokalnego grzania/chłodzenia ani pomiaru sygnałów.',
    'Na linii analogowej jest 1.7 V. Nie znamy oczekiwanej wartości, źródła sygnału ani napięcia referencyjnego.',
    'Zasilacz pobiera więcej prądu niż zwykle, ale brak wartości referencyjnej, termowizji i rezystancji szyn do masy.',
    'Oscyloskop pokazuje nieregularny przebieg, ale nie podano skali czasu, amplitudy, punktu pomiarowego ani stanu obciążenia.'
],1):
    add(f'P55-UNK-{i:02d}','insufficient_data',p+' Podaj diagnozę zgodnie z zasadą niezgadywania: co można powiedzieć, jaki jeden test ma największą wartość rozdzielającą i co przewidujesz?', 'brak danych do jednoznacznego modelu usterki; należy utrzymać kilka hipotez zamiast wskazywać konkretny element', 'najpierw zebrać brakujący pomiar rozdzielający adekwatny do objawu: zasilania i reset, wejście/wyjście stopnia, lokalna korelacja termiczna lub kompletny przebieg oscyloskopowy', 'bez dodatkowego pomiaru nie ma unikalnego przewidywania; wynik testu ma dopiero rozdzielić hipotezy', True)
OUT.parent.mkdir(parents=True,exist_ok=True)
OUT.write_text('\n'.join(json.dumps(r,ensure_ascii=False) for r in rows)+'\n')
print(f'P5_5_CASES={len(rows)} path={OUT}')
